def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd
    import sys, os, shutil

    def quote_path(path: str) -> str:
        return f'"{path}"' if ' ' in path else path

    # Resolve the interpreter if needed (issue 8557)
    exe = cmd[0]
    if sys.platform.startswith('win'):
        if not os.path.isabs(exe) and not os.path.exists(exe):
            found = shutil.which(exe)
            if found:
                exe = found

    # If the command includes a script, inspect its shebang line
    if len(cmd) >= 2:
        script = cmd[1]
        if os.path.isfile(script):
            try:
                with open(script, 'rb') as f:
                    first_line = f.readline()
                if first_line.startswith(b'#!'):
                    shebang = first_line[2:].strip().decode('utf-8', errors='ignore')
                    parts = shebang.split()
                    if parts:
                        interpreter_raw = parts[0]
                        if not os.path.isabs(interpreter_raw):
                            resolved = shutil.which(interpreter_raw)
                            if resolved:
                                interpreter_raw = resolved
                        interpreter = quote_path(interpreter_raw)
                        # Build a new command tuple with the interpreter
                        cmd = (interpreter,) + cmd[1:]
            except OSError:
                pass

    return cmd

