    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}
    # Iterate over resources defined in the manifest
    for resource_name, resource_obj in getattr(app.spec, "manifest", {}).items():
        # Check for a custom observer schema
        custom_schema = None
        if hasattr(resource_obj, "observer_schema"):
            custom_schema = getattr(resource_obj, "observer_schema")
